import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_svg/svg.dart';

import '../providers/global/prefs_provider.dart';
import '../utilities/assets.dart';

/// Masks a balance and temporarily reveals it without changing the preference.
class HideableBalance extends ConsumerStatefulWidget {
  const HideableBalance({
    super.key,
    required this.child,
    this.iconColor,
    this.iconSize = 20,
  });

  final Widget child;
  final Color? iconColor;
  final double iconSize;

  static const Duration revealDuration = Duration(seconds: 3);

  @override
  ConsumerState<HideableBalance> createState() => _HideableBalanceState();
}

class _HideableBalanceState extends ConsumerState<HideableBalance> {
  Timer? _revealTimer;
  bool _revealed = false;

  void _reveal() {
    _revealTimer?.cancel();
    setState(() {
      _revealed = true;
    });
    _revealTimer = Timer(HideableBalance.revealDuration, () {
      if (mounted) {
        setState(() {
          _revealed = false;
        });
      }
    });
  }

  @override
  void dispose() {
    _revealTimer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final hideBalances = ref.watch(hideBalancesProvider);

    if (!hideBalances || _revealed) {
      return widget.child;
    }

    // IconButton publishes the button/enabled/focus flags, the focus action
    // and the tooltip as the accessible name; an enclosing Semantics node
    // would mask all of it.
    return IconButton(
      tooltip: "Show balance temporarily",
      onPressed: _reveal,
      padding: EdgeInsets.zero,
      constraints: const BoxConstraints(minWidth: 24, minHeight: 24),
      visualDensity: VisualDensity.compact,
      icon: SvgPicture.asset(
        Assets.svg.eyeSlash,
        semanticsLabel: "Show balance temporarily",
        colorFilter: widget.iconColor == null
            ? null
            : ColorFilter.mode(widget.iconColor!, BlendMode.srcIn),
        width: widget.iconSize,
        height: widget.iconSize,
      ),
    );
  }
}
